from future import standard_library
standard_library.install_aliases()
logger = BackgroundLogger.Instance()


class ScapyTool(ToolBase):
    TOOL = "scapy"

    def __init__(self, device):
        self.device = device
        self.session = None
        self.root = None
        self.sudo_dict = {'root': '', 'non-root': 'sudo'}
        self.base_interface = get_config_variable(['generators', self.device, 'interface'])
        self.bts_id = get_config_variable(['bts_id'])

    def traffic_setup(self):
        logger.info("Setting up traffic...")
        ip, user, password, prompt = self._get_scapy_credentials()
        self.session = self.login_to_scapy_pc(user, ip, password, prompt)
        self.home_path = self._get_scapy_pc_home_path(user)

    def _get_scapy_credentials(self):
        ip = get_config_variable(['generators', self.device, 'ip'])
        user = get_config_variable(['generators', self.device, 'user'])
        password = get_config_variable(['generators', self.device, 'password'])
        prompt = get_config_variable(['generators', self.device, 'prompt'])
        return ip, user, password, prompt

    def traffic_start(self, profile):
        logger.debug("starting traffic....")
        self.pad1 = self.bts_id[:4]
        self.pad2 = datetime.now().strftime('%M%S')
        self.pad = str(int(self.pad1) + int(self.pad2))[:4]
        self.pad += 'a'*(4-len(self.pad))
        speed, duration = self._send_traffic(profile)
        return speed, duration

    def traffic_stop(self):
        pass

    def traffic_teardown(self):
        logger.debug("performing traffic teardown...")
        # self.exit_scapy_interface()
        self.session.close_all_connections()

    def _send_traffic(self, profile):
        traffic_profile = self._get_traffic_profile_from_profile(profile)
        count = self._get_count_value_from_profile(traffic_profile, profile)
        time_to_sleep = self.get_time_to_sleep_bw_packets(profile)
        self._configure_scapy_and_build_packet(profile)
        tcpdump_pid = self.start_tcpdump_capture(get_config_variable(['generators', self.device, 'interface']))
        self._send_packets(count, time_to_sleep)
        # self._send_commands_to_scapy(count, time_to_sleep, profile)
        self.stop_tcp_dump_capture(tcpdump_pid=tcpdump_pid)
        speed_attained, duration = self.get_packet_speed(pid=tcpdump_pid, protocol=get_config_variable(['traffic_profiles', profile, 'protocol']))
        self._delete_capture_file()
        return speed_attained, duration

    def _get_traffic_profile_from_profile(self, profile):
        traffic_profile = get_config_variable(['traffic_profiles', profile])
        if traffic_profile is None:
            raise Exception("Profile {} not found in config file".format(profile))
        logger.debug("traffic profile received :: {}".format(traffic_profile))
        return traffic_profile

    def _get_count_value_from_profile(self, traffic_profile, profile):
        if 'duration' in traffic_profile:
            count = self._get_count_based_on_duration(profile)
        elif 'packets' in traffic_profile:
            count = self._get_count_based_on_packets(profile)
        else:
            logger.info("duration/packets not given in profile, using default packets value 1")
            count = 10
        return count

    def _get_packet_speed_from_profile(self, profile):
        speed = get_config_variable(['traffic_profiles', profile, 'speed'])
        if speed is None:
            logger.info("Speed not given in profile, using default speed 1")
            speed = 1
        logger.info('Speed is : {0}'.format(speed))
        return speed

    def get_time_to_sleep_bw_packets(self, profile):
        speed = self._get_packet_speed_from_profile(profile)
        time_to_sleep = 1.0 / int(speed)
        logger.debug('Time between each packet = {0}'.format(time_to_sleep))
        return time_to_sleep

    def _send_commands_to_scapy(self, count, time_to_sleep, profile):
        logger.debug("sending commands to scapy....")
        self._send_packets(count, time_to_sleep)

    def _configure_scapy_and_build_packet(self, profile):
        self.prepare_scapy_interface()
        self._build_socket_bw_scapy_pc_and_dest()
        self._build_protocol_commands_from_profile(profile)
        vlan = get_config_variable(['traffic_profiles', profile, 'vlan'])
        self._bind_interface(vlan)
        self._build_packet()

    def _bind_interface(self, vlan):
        if vlan:
            interface = "{0}.{1}".format(self.base_interface.split(".")[0], vlan)
            self.session.write("s.bind(('{}', 0))".format(interface))
            self.session.read_until('>>>')

    def _build_socket_bw_scapy_pc_and_dest(self):
        self.session.write('s = socket.socket(socket.AF_PACKET, socket.SOCK_RAW)')
        self.session.read_until('>>>')
        self.session.write("s.bind(('{}', 0))".format(self.base_interface))
        self.session.read_until('>>>')

    def _build_protocol_commands_from_profile(self, profile):
        logger.debug("building protocols from profile...")
        pkt_details = dict(get_config_variable(['traffic_profiles', profile]))
        cmd = pkt_details.get("command", None)
        # pkt_details = self._replace_robot_variable_in_pkt_details(pkt_details, profile)

        # check for dhcp information. if it is not given, assign "" to dhcp_options (required while creating ipv4 commands)
        if "dhcp_options" in pkt_details.keys():
            pkt_details['dhcp_options'] = self._create_dhcp_opt_value(pkt_details['dhcp_options'])
        else:
            pkt_details['dhcp_options'] = ""

        if cmd is not None and cmd != '':
            cmd = 'pe=' + cmd + "/'{}'".format(self.pad)
            self.session.write(cmd)
        else:
            if pkt_details.get("ip_version") == 'ipv4':
                cmd = self._build_ipv4_command(pkt_details)
            elif pkt_details.get("ip_version") == 'ipv6':
                cmd = self._build_ipv6_command(pkt_details)
            self.session.write(cmd)

    def _create_dhcp_opt_value(self, opt_dict):
        # This function converts a dict (i.e., dhcp_options, taken from traffic profile) to a string that can be used to edit scapy commands
        opt_str = ""
        for key, val in opt_dict.items():
            val_qt = "\'"
            try:
                if val.isdigit():
                    opt_dict[key] = int(val)
            except AttributeError:
                pass
            if not isinstance(opt_dict[key], str):
                val_qt = ""
            opt_str += "(\'" + str(key) + "\'," + val_qt + str(val) + val_qt + "),"
        return opt_str

    def _replace_robot_variable_in_pkt_details(self, pkt_details, profile):
        logger.info("Pkt details :: {}".format(str(pkt_details)))
        for detail in list(pkt_details.keys()):
            if re.search(r"\$\{.*\}", str(pkt_details[detail])):
                pkt_details[detail] = get_config_variable(['traffic_profiles', profile, detail])
        return pkt_details

    def _build_ipv6_command(self, pkt_details):
        logger.debug("Building ipv6 command...")
        pad_string = ''
        if pkt_details.get("malformed") == 'true':
            if pkt_details.get("frame_size"):
                pad_string = '/' + 'a' * (int(pkt_details["frame_size)"]) - 30 - len(self.pad))
                pad_string += self.pad
        protocol = pkt_details.get("protocol").lower()
        other_protocols_dict = {'sctp': 'SCTP()',
                         'udp': 'UDP(sport={src_port},dport={dst_port})',
                         'ntp': 'UDP(sport=123, dport=123)',
                         'bfd': 'UDP(sport=3784, dport=3784)',
                         'isakmp': 'UDP(sport=500, dport=500)',
                         'ssh': 'TCP(sport=49666, dport=22)',
                         'http': 'TCP(sport=47096, dport=80)',
                         'https': 'TCP(sport=47096, dport=443)',
                         'ptp': 'UDP(sport=320, dport=320)'}
        if protocol == 'icmp':
            protocol_str ='pe=Ether()/IPv6(dst="{0}")/ICMPv6ND_RA(type={1}, code={2})/"{3}"'.format(
                pkt_details["destination"], pkt_details["type"], pkt_details["code"], self.pad)
        elif protocol == 'sctp':
            protocol_str = 'pe=Ether()/IPv6(src="{0}", dst="{1}", nh=132)/SCTP(sport={2}, dport ={3})/' \
                           'SCTPChunkInit()/"{4}"'.format(pkt_details["source"], pkt_details["destination"],
                                                    pkt_details["src_port"], pkt_details["dst_port"], self.pad)
        elif protocol == 'gtp':
            protocol_str = 'pe=Ether()/IPv6(src="{0}", dst="{1}")/UDP(sport={2}, dport={3})/GTP_U_Header(TEID=0x31)/' \
                           'IP()/UDP()/"{4}"'.format(pkt_details["source"], pkt_details["destination"],
                                                  pkt_details["src_port"], pkt_details["dst_port"], self.pad)
        elif protocol == 'dhcp':
            protocol_str = "pe=Ether() / IPv6(src='{0}', dst='{1}') / UDP(sport=68, dport=67) / BOOTP() / DHCP(options=[{2} 'end']) / '{3}'".format(pkt_details["source"], pkt_details["destination"], pkt_details["dhcp_options"], self.pad)

        elif protocol in list(other_protocols_dict.keys()):
        # elif protocol == 'udp' or protocol == 'ptp' or protocol == 'ntp' or protocol == 'bfd' or protocol == 'isakmp' or protocol == 'sctp' or protocol == 'ssh' or protocol == 'http' or protocol == 'https':
            common = "pe=Ether()/IPv6(src='{0}',dst='{1}')/".format(pkt_details["source"], pkt_details["destination"])
            #print protocol_dict.get(pkt_details["protocol"]
            protocol_str = common + other_protocols_dict.get(pkt_details["protocol"]) + "/'"+self.pad+"'"
            protocol_str = protocol_str.format(**pkt_details)
            print("protocol_str")
        else:
            raise Exception('Unsupported protocol: {}'.format(protocol))
        return protocol_str
        # self.session.write(protocol_str)

    def _build_ipv4_command(self, pkt_details):
        logger.debug("building ipv4 command....")
        if pkt_details.get("malformed") == 'true':
            if pkt_details.get("frame_size"):
                cmd = self._build_ipv4_packets_for_frame_size(pkt_details)
            elif pkt_details.get("src_port") or pkt_details.get("dst_port"):
                cmd = self._build_ipv4_packets_for_src_dst_port_option(pkt_details)
        else:
            cmd = self._build_ipv4_complete_detailed_packet(pkt_details)
        logger.debug("Scapy command for pkt: {}".format(cmd))
        return cmd
        # self.session.write(cmd)

    def _build_ipv4_packets_for_frame_size(self, pkt_details):
        if pkt_details.get("frame_size"):
            pad = 'a' * (int(pkt_details["frame_size"]) - 30 - len(self.pad))
            pad += self.pad
            return "pe=Ether()/IP(src={0}, dst='{1}')/SCTP()/'{2}')/SCTPChunkInit()".format(pkt_details["source"],
                                                                           pkt_details["destination"], pad)

    def _build_ipv4_packets_for_src_dst_port_option(self, pkt_details):
        if pkt_details.get("protocol").lower() == 'sctp':
            return "pe=Ether()/IP(src='{0}', dst='{1}')/SCTP(sport={2}, dport={3})/SCTPChunkInit()/'{4}'".format(pkt_details["source"],
                                                                                          pkt_details["destination"],
                                                                                          pkt_details["src_port"],
                                                                                          pkt_details["dst_port"],
                                                                                          self.pad)
        else:
            return "pe=Ether()/IP(src='{0}', dst='{1}')/UDP(sport={2}, dport={3})/'{4}'".format(pkt_details["source"],
                                                                                         pkt_details["destination"],
                                                                                         pkt_details["src_port"],
                                                                                         pkt_details["dst_port"],
                                                                                                self.pad)

    def _build_ipv4_complete_detailed_packet(self, pkt_details):
        common = "pe=Ether()/IP(src='{0}',dst='{1}')/{{}}/'{2}'".format(pkt_details["source"],
                                                                        pkt_details["destination"], self.pad)
        protocol_dict = {'sctp': common.format('SCTP()/SCTPChunkInit()'),
                         'udp': common.format('UDP()'),
                         'ntp': common.format('UDP(sport=123, dport=123)'),
                         'bfd': common.format('UDP(sport=3784, dport=3784)'),
                         'icmp': common.format('ICMP()'),
                         'isakmp': common.format('UDP(sport=500, dport=500)'),
                         'gtp': common.format('UDP(sport=2152, dport=2152)/GTP_U_Header(TEID=0x31)'),
                         'ssh': common.format('TCP(sport=49666, dport=22)'),
                         'http': common.format('TCP(sport=47096, dport=80)'),
                         'https': common.format('TCP(sport=47096, dport=443)'),
                         'arp': 'pe=Ether(type=0x0806)/ARP(pdst="' + pkt_details["destination"] + '")'+"/'{}'".format(self.pad),
                         'ptp': 'pe=Ether()/IP(src="' + pkt_details["source"] + '", dst="' + pkt_details["destination"]
                                + '")/UDP(sport=320, dport=320)'+"/'{}'".format(self.pad),
                         'twamp': 'pe=Ether()/IP(src=\'' + pkt_details["source"] + '\',dst=\'' + pkt_details[
                             "destination"] + '\', len=100, flags=2)/UDP(sport=5004,dport=5018,len=80)/TWAMP()'+"/'{}'".format(self.pad),
                         'dhcp': "pe=Ether() / IP(src='{0}', dst='{1}') / UDP(sport=68, dport=67) / BOOTP() / DHCP(options=[{2} 'end']) / '{3}'".format(pkt_details["source"],pkt_details["destination"],pkt_details.get("dhcp_options"),self.pad)
                         }

        return protocol_dict.get(pkt_details["protocol"])

    def _send_packets(self, count, time_to_sleep):
        logger.debug("sending packets....")
        self.session.write('while iter < {0}:'.format(count))
        self.session.read_until('...')
        self.session.write('        l=s.send(data);iter=iter+1;sleep({0})'.format(time_to_sleep))
        self.session.read_until('...')
        self.session.write('')
        self.session.set_client_configuration(timeout='10 minutes')
        self.session.read_until('>>>')

    def _build_packet(self):
        # command_list = ['data = pe.build()', "print 'test'", "print 'test'", 'print len(data)']
        command_list = ['data = pe.build()', 'iter = 0', "", "print('packet len:{}'.format(len(data)))"]
        for command in command_list:
            self.session.write(command)
            output = self.session.read(delay='1s')
        self._get_packet_len(output)

    def _get_packet_len(self, output):
        logger.debug('Packet length output: {}#'.format(output))
        self.packet_len = int(re.findall(r'packet len:(\d+)', output)[0])
        logger.debug('Packet Length: {}#'.format(self.packet_len))

    def _send_l3_packets(self, count, time_to_sleep):
        logger.debug("sending L3 packets....")
        command_list = ['iter = 0']
        for command in command_list:
            self.session.write(command)
        self.session.read_until('>>>')
        self.session.write('while iter < {0}:'.format(count))
        self.session.read_until('...')
        self.session.write('        l=socket_l3.send(pe);iter=iter+1;sleep({0})'.format(time_to_sleep))
        self.session.read_until('...')
        self.session.write('')
        self.session.set_client_configuration(timeout='10 minutes')
        self.session.read_until('>>>')

    def _get_count_based_on_packets(self, profile):
        speed = get_config_variable(['traffic_profiles', profile, 'speed'])
        logger.debug("getting count based on packets....")
        packets_count = get_config_variable(['traffic_profiles', profile, 'packets'])
        logger.debug('No. of packets = {0}'.format(packets_count))
        return packets_count

    def _get_count_based_on_duration(self, profile):
        speed = get_config_variable(['traffic_profiles', profile, 'speed'])
        logger.debug("getting count based on duration....")
        duration = get_config_variable(['traffic_profiles', profile, 'duration'])
        packets_count = int(speed) * int(duration)
        logger.debug('No. of packets = {0}'.format(packets_count))
        logger.debug('Duration is = {0}'.format(duration))
        return packets_count

    def login_to_scapy_pc(self, user, ip, password, prompt):
        logger.debug("logging to scapy pc....")
        if user == 'None' or ip == 'None':
            raise Exception("Invalid login credentials")
        pc_session = SSHLibrary.SSHLibrary(timeout=120)
        try:
            pc_session.open_connection(host=ip, prompt=prompt, timeout=120)
            sleep(1)
            self._ssh_auth_options(pc_session, user, password)
        except Exception as error_login:
            raise Exception("SSH Connection to scapy failed due to {}".format(error_login))
        self._is_user_root(pc_session)
        return pc_session

    def _ssh_auth_options(self, ssh_handle, user, password=None):
        if password is not None:
            logger.info("Performing password based login")
            ssh_handle.login(username=user, password=password)
        else:
            logger.info("Performing key based login")
            ssh_handle.login_with_public_key(username=user, keyfile='/home/ute/.ssh/authorized_keys', look_for_keys=True)

    def  _is_user_root(self, ssh_handle):
        out, err, rc = ssh_handle.execute_command('id', return_stderr=True, return_rc=True)
        matches = re.finditer(r'uid=(\d+)', out, re.MULTILINE | re.DOTALL | re.IGNORECASE)
        for match in matches:
            self.root = 'root' if match.group(1) == 0 else 'non-root'
        logger.info("User has logged in as {}".format(self.root))

    def prepare_scapy_interface(self):
        logger.debug("preparing scapy interface....")
        sys_path = self._find_sys_path()
        # command_list = ['sudo python', '', '', 'from scapy.all import *',
        command_list = ['python', '', '', 'from scapy.all import *',
                        'import sys', '', '',
                        'sys.path.insert(0,"{0}")'.format(sys_path), '', '',
                        'from taf.ul.trs_e2e_fw.lib.traffic.generator.scapy_protocols.scapy_gtp import *', '', '',
                        'from taf.ul.trs_e2e_fw.lib.traffic.generator.scapy_protocols.scapy_twamp import TWAMP', '', '',
                        'from time import sleep']
        for command in command_list:
            self.session.write(command)
            self.session.read_until('>>>')

    def _find_sys_path(self):
        path_list = sys.path
        for i in path_list:
            if re.search('/site-packages$', decode_str(i)):
                return i

    def exit_scapy_interface(self):
        logger.debug("exiting scapy interface...")
        self.session.write('exit()')
        self.session.read_until(get_config_variable(['generators', self.device, 'prompt']))

    def start_tcpdump_capture(self, interface=None):
        logger.debug("starting tcpdump capture....")
        self.pcap_file = '{home}/tcpdump_capture_{btsid}.pcap'.format(home=self.home_path, btsid=self.bts_id)
        # tcpdump_cmd = self.sudo_dict.get(self.root) + ' tcpdump -i {0} src {1} and dst {2} -w {3} >/dev/null 2>/dev/null & echo $!'.format(interface, src, dest, self.pcap_file)
        pad_hex = '0x' + "".join("{:02x}".format(ord(c)) for c in self.pad)
        pad_pos = self.packet_len - 4
        tcpdump_cmd = self.sudo_dict.get(
            self.root) + ' tcpdump -i {} -xx ether[{}:4]=={} -w {} >/dev/null 2>/dev/null' \
                         ' & echo $!'.format(interface, pad_pos, pad_hex, self.pcap_file)
        logger.debug('Capturing tcpdump with command : {0}'.format(tcpdump_cmd))
        out, err, rc = self.session.execute_command(tcpdump_cmd, return_stderr=True, return_rc=True)
        logger.debug("tcpdump exection output:".format(out))
        out, err = out.strip(), err.strip()
        if rc == 0:
            logger.debug("tcpdump exection output:".format(out))
            return out
        else:
            raise Exception("Error in starting tcpdump:{}".format(err))

    def stop_tcp_dump_capture(self, tcpdump_pid):
        sleep(7)
        self.session.execute_command("sudo kill {}".format(tcpdump_pid))

    def _delete_capture_file(self):
        self.session.execute_command("rm -f tcpdump_capture_{0}.pcap".format(self.bts_id))
        self.session.execute_command("rm -f tcpdump_capture_{0}.txt".format(self.bts_id))

    def get_packet_speed(self, pid=None, protocol=None):
        logger.debug("getting packet speed....")
        # home_folder = expanduser("~")
        pcap_txt_file = self.home_path + '/tcpdump_capture_' + self.bts_id + '.txt'
        # pcap_filename = home_folder + '/tcpdump_capture_' + btsid + '.pcap'
        self.session.get_file(self.pcap_file, 'execution_logs/')
        out, err, rc = self.session.execute_command(self.sudo_dict.get(self.root) + ' tcpdump -r {0} -ttttt >{1}'.format(self.pcap_file,pcap_txt_file), return_stderr=True, return_rc=True)
        if rc == 1:
            raise Exception("Error in generating tcpdump text file:{}".format(err))
        self.session.get_file(pcap_txt_file, 'execution_logs/')
        if os.stat('execution_logs/tcpdump_capture_' + self.bts_id + '.txt').st_size == 0:
            raise Exception("Generated tcpdump text file is empty. No packets were sent.")
        delta_t = self.get_delta_time(pcap_txt_file, protocol)
        self.session.start_command('cat {0} | wc -l'.format(pcap_txt_file))
        packets = self.session.read_command_output()
        logger.debug('Number of packets sent :{}'.format(packets))
        speed = int(packets) / delta_t
        logger.debug('Speed Achieved is about : {0} per second'.format(speed))
        return speed, delta_t

    def get_delta_time(self, filename, protocol):
        logger.debug("getting delta time....")
        # grep_command = 'grep -i {0} {1} | tail -n 1'.format(protocol, filename)
        grep_command = 'tail -n 1 {}'.format(filename)
        self.session.start_command(grep_command)
        last_packet = self.session.read_command_output()
        logger.debug("Last Packet string: {}".format(last_packet))
        if last_packet == '':
            raise Exception("Protocol {} not found in captured data".format(protocol))
        time_str = last_packet[:15]
        logger.debug("Time string: {}".format(time_str))
        milli_seconds_str = time_str.split(".")[1]
        h_m_s_str = time_str.split(".")[0]
        h_m_s = h_m_s_str.split(":")
        milli_seconds = int(milli_seconds_str) / float(1000000)
        delta_time = int(h_m_s[0]) * 60 * 60 + int(h_m_s[1]) * 60 + int(h_m_s[2]) + milli_seconds
        logger.debug('Time in which packets were sent : {0}'.format(delta_time))
        return delta_time

    def _get_scapy_pc_home_path(self, user):
        out = self.session.execute_command('getent passwd {user} | cut -d: -f6 '.format(user=user))
        logger.debug('Scapy PC HOME path: {} ##'.format(out))
        return out

    def traffic_capture_and_replay(self, capture_interface, replay_interface, capture_filter, num_pkts_to_send, delay, pcap_filepath, **kwargs):
        modify_string = None
        if capture_interface is None:
            raise Exception("Capture interface is mandatory argument. Kindly provide capture interface...")
        scapy_script = os.path.abspath(os.path.join(__file__, os.pardir, 'scapy_replay.py'))
        self.session.put_file(scapy_script, "scapy_replay.py")
        for key, value in list(kwargs.items()):
            modify_string = str(key) + '=' + str(value)
            modify_string += ','

        replay_command = "python scapy_replay.py -c {0} -r {1} -f \"{2}\" -n {3} -d {4}".format(capture_interface, replay_interface, capture_filter, num_pkts_to_send, delay)

        if modify_string:
            replay_command = replay_command + ' -m ' + modify_string[:-1]
        logger.debug("Command: {0}".format(replay_command))

        out, err = self.session.execute_command(replay_command, return_stderr=True)
        logger.debug(out, err)
